+import { Hono } from 'hono';
+import { sign } from 'hono/jwt';
+
+export const authRoutes = new Hono();
+
+authRoutes.post('/recruiter', async (c) => {
+  const { email, password } = await c.req.json();
+  const user = await c.env.DB
+    .prepare('SELECT id, password_hash FROM recruiters WHERE email = ?1')
+    .bind(email)
+    .first();
+  if (!user) return c.json({ error: 'invalid_credentials' }, 401);
+
+  const valid = await bcryptCompare(password, user.password_hash);
+  if (!valid) return c.json({ error: 'invalid_credentials' }, 401);
+
+  const token = await sign({ sub: user.id, role: 'recruiter' }, c.env.JWT_SECRET);
+  return c.json({ token });
+});
